/** Workers-safe SSE framing (no imports from Node hub graph). */
function isRealtimeError(message) {
    return (typeof message === "object" &&
        message !== null &&
        "code" in message &&
        "message" in message &&
        !("channel" in message));
}
export function formatSseEvent(message) {
    if (isRealtimeError(message)) {
        return `event: error\ndata: ${JSON.stringify(message)}\n\n`;
    }
    return `id: ${message.id}\nevent: ${message.type}\ndata: ${JSON.stringify({
        channel: message.channel,
        room: message.room,
        data: message.data,
        timestamp: message.timestamp,
    })}\n\n`;
}
export function formatSseComment(comment) {
    return `: ${comment}\n\n`;
}
export function formatGapEvent(code) {
    return `event: gap\ndata: ${JSON.stringify({ code })}\n\n`;
}
